import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.UjrY2eRK.js";const g=JSON.parse('{"title":"Issue 26: UI integration constraints","description":"","frontmatter":{},"headers":[],"relativePath":"research/issue-26-ui-integrations.md","filePath":"research/issue-26-ui-integrations.md","lastUpdated":1788169631000}'),s={name:"research/issue-26-ui-integrations.md"};function o(n,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="issue-26-ui-integration-constraints" tabindex="-1">Issue 26: UI integration constraints <a class="header-anchor" href="#issue-26-ui-integration-constraints" aria-label="Permalink to &quot;Issue 26: UI integration constraints&quot;">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Keep the five feature routes as lazy standalone Angular routes and build their state from Angular signals, the generated <code>HttpClient</code> client, and the existing small <code>RemoteResource</code> abstraction. Do not add a client-state, query, chart wrapper, date, or second form library.</p><p>Keep Chart.js and ng-forge out of the initial bundle by importing them only from routes that use them. The one dependency still needed for the accepted test contract is exact <code>@axe-core/playwright@4.13.0</code> as a development dependency. Its package brings <code>axe-core~4.13.0</code> and accepts <code>playwright-core &gt;=1.0.0</code>, so it is compatible with the repository-pinned Playwright 1.62.1 (<a href="https://github.com/dequelabs/axe-core-npm/blob/v4.13.0/packages/playwright/package.json" target="_blank" rel="noreferrer">exact package manifest</a>).</p><p>The repository pins Angular 22.1.4, <code>@spartan-ng/brain</code> 1.3.4, ng-forge 1.1.0, Chart.js 4.5.1, and Playwright 1.62.1. The package contracts are mutually compatible: Spartan 1.3.4 accepts Angular/CDK 21 or 22 and marks Brain as side-effect-free (<a href="https://github.com/spartan-ng/spartan/blob/v1.3.4/libs/brain/package.json" target="_blank" rel="noreferrer">manifest</a>); ng-forge 1.1.0 requires Angular 22 and is also side-effect-free (<a href="https://github.com/ng-forge/ng-forge/blob/v1.1.0/packages/dynamic-forms/package.json" target="_blank" rel="noreferrer">manifest</a>).</p><h2 id="route-allocation" tabindex="-1">Route allocation <a class="header-anchor" href="#route-allocation" aria-label="Permalink to &quot;Route allocation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>External integration</th><th>Constraint</th></tr></thead><tbody><tr><td>Overview</td><td>Angular signals and generated API only</td><td>Poll every 30 seconds while visible, preserve stale success, and remain chart-free.</td></tr><tr><td>Metrics</td><td>ng-forge, modular Chart.js, native <code>Intl</code></td><td>The range/interval controls are user-entered filters, so they fall under the ng-forge requirement. Poll only a range that includes the current UTC bucket.</td></tr><tr><td>Operations</td><td>ng-forge, native dialog, Spartan controls</td><td>Confirm Firebase validation, cleanup, and backup explicitly; keep action status and cooldown/deadline text in the dialog.</td></tr><tr><td>Configuration</td><td>Angular signals and generated API only</td><td>Render read-only safe values; do not instantiate a form library.</td></tr><tr><td>Security</td><td>ng-forge, native dialog, Spartan controls</td><td>Audit filters are user-entered; session revocation is a confirmed mutation. Keep opaque cursor state outside the form value.</td></tr></tbody></table><p>Angular route-level providers are scoped to a route and its children (<a href="https://angular.dev/guide/routing/define-routes#route-level-providers-for-dependency-injection" target="_blank" rel="noreferrer">route-provider contract</a>). Therefore, provide the minimal ng-forge adapter independently on Metrics, Operations, and Security. Do not move it to the shell route: that would make a large optional integration reachable from the initial navigation. Angular&#39;s <code>loadComponent</code> and <code>loadChildren</code> split lazy routes into separately requested chunks (<a href="https://angular.dev/guide/routing/loading-strategies#lazily-loaded-components-and-routes" target="_blank" rel="noreferrer">loading strategy</a>).</p><p>The existing source guard currently treats “route-local” as “Operations-only.” Issue #26 must update that guard to allow the shared adapter only from the three form-bearing lazy routes. The accepted requirement is not satisfied by using ordinary controls for Metrics or Security filters.</p><h2 id="angular-22-router-signals-and-polling" tabindex="-1">Angular 22 router, signals, and polling <a class="header-anchor" href="#angular-22-router-signals-and-polling" aria-label="Permalink to &quot;Angular 22 router, signals, and polling&quot;">​</a></h2><ul><li>Keep mutable remote state in writable signals and derive totals, labels, disabled states, empty states, and stale banners with <code>computed()</code>. In a zoneless application, updating a signal read by a template is an Angular change-detection notification; <code>OnPush</code> is the recommended compatibility shape (<a href="https://angular.dev/guide/zoneless#requirements-for-zoneless-compatibility" target="_blank" rel="noreferrer">zoneless requirements</a>).</li><li>Reserve <code>effect()</code> for the imperative boundaries: synchronizing a Chart.js instance and the local-only theme/time-zone preference. Angular explicitly identifies canvas/chart rendering as an appropriate effect use and advises <code>computed()</code> rather than effects for derived state (<a href="https://angular.dev/guide/signals/effect#use-cases-for-effects" target="_blank" rel="noreferrer">effect guidance</a>).</li><li>Initialize Chart.js after the canvas exists with <code>afterNextRender</code>; Angular documents this hook for one-time DOM setup of non-Angular libraries (<a href="https://angular.dev/api/core/afterNextRender" target="_blank" rel="noreferrer">API</a>). Destroy the Chart.js instance on route-component destruction.</li><li>Subscribe to route/poll observables with <code>takeUntilDestroyed()</code> so a lazy route stops work when it is left; the operator completes its source when the owning component or service is destroyed (<a href="https://angular.dev/api/core/rxjs-interop/takeUntilDestroyed" target="_blank" rel="noreferrer">API</a>).</li><li>Implement the 30-second rule from <code>Document.hidden</code> plus <code>visibilitychange</code>. The platform standard defines both and fires the event when document visibility changes (<a href="https://html.spec.whatwg.org/multipage/interaction.html#page-visibility" target="_blank" rel="noreferrer">HTML visibility model</a>). An RxJS <code>switchMap</code> from visibility to <code>timer(0, 30_000)</code> and <code>NEVER</code>, with <code>exhaustMap</code> around the HTTP call, has the right behavior: resume immediately on visibility, stop when hidden, and never overlap polls. The resulting subscription must call the resource&#39;s load method so an error changes a previous success to stale rather than replacing its data.</li><li>“Current Metrics” means the selected <code>to</code> boundary includes the current UTC hour/day bucket. Historical queries should load on filter submission or manual retry but should not acquire a timer.</li><li>Use <code>Intl.DateTimeFormat(undefined, options)</code> for browser-locale display. An omitted <code>timeZone</code> uses the host environment&#39;s zone; <code>timeZone: &#39;UTC&#39;</code> selects the explicit UTC view, and <code>timeZoneName</code> provides a visible zone label (<a href="https://402.ecma-international.org/#sec-properties-of-intl-datetimeformat-instances" target="_blank" rel="noreferrer">ECMA-402 DateTimeFormat contract</a>). This avoids Luxon and a Chart.js time adapter. Keep the wire/query values as ISO UTC strings and use a <code>CategoryScale</code> with preformatted labels.</li></ul><h2 id="ng-forge-1-1-0-and-spartan-1-3-4" tabindex="-1">ng-forge 1.1.0 and Spartan 1.3.4 <a class="header-anchor" href="#ng-forge-1-1-0-and-spartan-1-3-4" aria-label="Permalink to &quot;ng-forge 1.1.0 and Spartan 1.3.4&quot;">​</a></h2><p>The existing custom adapter follows ng-forge&#39;s exact supported seam: <code>provideDynamicForm</code>, a <code>FieldTypeDefinition</code> per type, category mappers, <code>NgForgeFieldHost</code>/<code>NgForgeActionHost</code>, <code>[formField]</code>, and <code>NgForgeControl</code>. The latter is important because it forwards the library&#39;s derived <code>aria-invalid</code>, <code>aria-required</code>, <code>aria-describedby</code>, and metadata to the canonical native control (<a href="https://github.com/ng-forge/ng-forge/blob/v1.1.0/apps/docs/public/content/building-an-adapter.md" target="_blank" rel="noreferrer">1.1.0 adapter guide</a>).</p><p>Implementation constraints:</p><ul><li>Continue authoring configs as <code>as const satisfies FormConfig</code> and validate them with the existing Zod Standard Schema wrapper. ng-forge maps Standard Schema issue paths to their corresponding Signal Form fields (<a href="https://github.com/ng-forge/ng-forge/blob/v1.1.0/apps/docs/public/content/schema-validation/zod.md" target="_blank" rel="noreferrer">Zod integration</a>).</li><li>The repository patch deliberately removes ng-forge&#39;s built-in fields, wrappers, containers, addons, and paged-form loader. All issue #26 forms must therefore stay flat and use only the registered <code>input</code>, <code>datetime</code>, <code>select</code>, <code>checkbox</code>, and <code>submit</code> types. Do not introduce <code>row</code>, <code>group</code>, <code>page</code>, <code>text</code>, wrapper, or addon config types.</li><li>Promote the adapter from an Operations-specific path to a shared lazy-feature path, but keep providers on the individual form-bearing routes. This shares source without making ng-forge an application-root dependency.</li><li>A <code>datetime-local</code> value contains no zone. Convert it according to the explicitly displayed local/UTC mode before calling the API, validate <code>from &lt; to</code> and the 30-day bound in Zod, and never pass the raw local string as an API timestamp.</li><li>For asynchronous confirmation forms, prefer ng-forge&#39;s <code>submission.action</code>. It supplies a submitting state and disables submit buttons while the returned Promise/Observable is pending. The resolved value is discarded, and action errors are caught by the library, so the action must catch/map server problems into the page&#39;s own safe status signal (<a href="https://github.com/ng-forge/ng-forge/blob/v1.1.0/apps/docs/public/content/dynamic-behavior/submission.md" target="_blank" rel="noreferrer">submission contract</a>). If manual <code>(submitted)</code> handling is retained instead, add an explicit pending guard; otherwise rapid submits can duplicate a mutation.</li></ul><p>Use app-owned Helm-style wrappers over individual Brain entry points rather than adding <code>@spartan-ng/helm</code> or the Spartan CLI. Brain is already the runtime dependency; the project&#39;s copied wrappers keep styles and imports auditable.</p><p>For destructive or bounded operator actions, Spartan&#39;s alert-dialog primitive has the right defaults: it changes the role to <code>alertdialog</code> and disables outside-pointer dismissal (<a href="https://github.com/spartan-ng/spartan/blob/v1.3.4/libs/brain/alert-dialog/src/lib/brn-alert-dialog.ts" target="_blank" rel="noreferrer">1.3.4 source</a>). The underlying dialog defaults autofocus the first tabbable control and restore focus to the trigger (<a href="https://github.com/spartan-ng/spartan/blob/v1.3.4/libs/brain/dialog/src/lib/brn-dialog-token.ts" target="_blank" rel="noreferrer">defaults</a>). Still test focus trapping, Escape, trigger restoration, and accessible title/description explicitly.</p><p>Two exact-version pitfalls matter:</p><ol><li>Alert dialogs still close on Escape unless <code>disableClose</code> is set. Disable closing only while a mutation is pending; outside-pointer dismissal is already disabled.</li><li>Spartan&#39;s Helm <code>hlmAlertDialogAction</code> styles the action but does not close the dialog, while its cancel directive composes <code>BrnDialogClose</code> (<a href="https://github.com/spartan-ng/spartan/blob/v1.3.4/libs/helm/alert-dialog/src/lib/hlm-alert-dialog-action.ts" target="_blank" rel="noreferrer">action source</a>, <a href="https://github.com/spartan-ng/spartan/blob/v1.3.4/libs/helm/alert-dialog/src/lib/hlm-alert-dialog-cancel.ts" target="_blank" rel="noreferrer">cancel source</a>). Close explicitly through the portal context after a successful action; keep the dialog open with a safe problem/status announcement on failure.</li></ol><p>The optimized implementation build changed the final selection. Importing the Brain/CDK dialog stack added 65.8 KiB of minified JavaScript and pushed the accepted browser output over its 1 MiB hard cap. The delivered confirmation uses the platform <code>&lt;dialog role=&quot;alertdialog&quot;&gt;</code> primitive, Spartan buttons, and the shared ng-forge confirmation field instead. It retains modal focus, Escape cancellation outside a pending mutation, trigger-focus restoration, explicit success close, and failure-in-place behavior without shipping the CDK overlay runtime.</p><h2 id="chart-js-4-5-1-accessibility-and-csp" tabindex="-1">Chart.js 4.5.1, accessibility, and CSP <a class="header-anchor" href="#chart-js-4-5-1-accessibility-and-csp" aria-label="Permalink to &quot;Chart.js 4.5.1, accessibility, and CSP&quot;">​</a></h2><p>Import from <code>chart.js</code>, never <code>chart.js/auto</code>. Chart.js is tree-shakeable only when the needed controllers, elements, scales, and plugins are explicitly registered (<a href="https://www.chartjs.org/docs/latest/getting-started/integration.html#bundlers-webpack-rollup-etc" target="_blank" rel="noreferrer">bundler integration</a>). The exact set for issue #26 is:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Chart.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  BarController,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  BarElement,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LineController,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LineElement,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PointElement,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CategoryScale,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  LinearScale,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Legend,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tooltip,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Use stacked bar datasets for request outcomes and FCM outcomes with <code>scales.x.stacked</code> and <code>scales.y.stacked</code>; this is the documented stacked-bar configuration (<a href="https://www.chartjs.org/docs/latest/samples/bar/stacked.html" target="_blank" rel="noreferrer">sample</a>). The approximate p95 series can be a line dataset with its own linear axis. Chart.js mixed charts set <code>type</code> on each dataset, and their chart-type defaults are not merged at the chart level (<a href="https://www.chartjs.org/docs/latest/charts/mixed.html" target="_blank" rel="noreferrer">mixed-chart contract</a>). For a simpler and more legible result, three small charts—request outcomes, FCM outcomes, and p95 latency—are preferable to one overloaded mixed chart and use the same registered set.</p><p>Set <code>animation: false</code> for every chart and use <code>chart.update(&#39;none&#39;)</code> for poll updates. Chart.js documents both the global animation-off switch and the no-animation update mode (<a href="https://www.chartjs.org/docs/latest/configuration/animations.html#disabling-animation" target="_blank" rel="noreferrer">animations</a>, <a href="https://www.chartjs.org/docs/latest/developers/updates.html#preventing-animations" target="_blank" rel="noreferrer">updates</a>). Call <code>destroy()</code> on component teardown; it releases Chart.js references and event listeners (<a href="https://www.chartjs.org/docs/latest/developers/api.html#destroy" target="_blank" rel="noreferrer">API</a>).</p><p>A canvas is not a semantic data representation. Chart.js explicitly leaves canvas accessibility to the author (<a href="https://www.chartjs.org/docs/latest/general/accessibility.html" target="_blank" rel="noreferrer">accessibility guidance</a>). Every chart therefore needs an equivalent ordinary table that includes every UTC bucket and every displayed series, including approximate p95 values. Keep the table available in all color schemes and forced-colors mode; do not make it a visually hidden summary. The canvas may have an accessible name, but the table is the authoritative screen-reader and non-color representation.</p><p>The production CSP can remain unchanged. Angular applies the request nonce from <code>ngCspNonce</code> to framework-created style elements (<a href="https://angular.dev/best-practices/security#content-security-policy" target="_blank" rel="noreferrer">Angular CSP contract</a>). Chart.js uses canvas and programmatic element styles, while Spartan/CDK overlays position elements with style attributes; the existing narrow <code>style-src-attr &#39;unsafe-inline&#39;</code> allowance accommodates these without adding <code>unsafe-inline</code> or <code>unsafe-eval</code> to <code>script-src</code>. Prove this on the real nonce-bearing production asset server with <code>securitypolicyviolation</code>, console, page-error, and failed-request assertions; a static-file smoke is not enough.</p><h2 id="playwright-1-62-1-and-axe" tabindex="-1">Playwright 1.62.1 and axe <a class="header-anchor" href="#playwright-1-62-1-and-axe" aria-label="Permalink to &quot;Playwright 1.62.1 and axe&quot;">​</a></h2><p>Configure four projects:</p><ul><li>Chromium (<code>Desktop Chrome</code>): every functional flow, every route/state axe scan, CSP, forced-colors, reduced-motion, and proof capture.</li><li>Firefox (<code>Desktop Firefox</code>): tagged login, navigation, logout, and keyboard smoke.</li><li>WebKit (<code>Desktop Safari</code>): the same tagged cross-browser smoke.</li><li>Mobile WebKit (<code>iPhone 13</code>): tagged drawer/navigation and responsive route smoke.</li></ul><p>Playwright&#39;s official browser matrix uses <code>Desktop Safari</code> for WebKit and an iPhone device profile for Mobile Safari (<a href="https://playwright.dev/docs/browsers#run-tests-on-different-browsers" target="_blank" rel="noreferrer">browser projects</a>, <a href="https://playwright.dev/docs/emulation#devices" target="_blank" rel="noreferrer">device emulation</a>). Use project <code>grep</code> tags so Chromium runs everything while the other projects run only their accepted subset; project-level filtering is a documented use of <code>grep</code> (<a href="https://playwright.dev/docs/api/class-testproject#test-project-grep" target="_blank" rel="noreferrer">TestProject</a>).</p><p>Build an axe fixture with:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AxeBuilder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ page }).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">withTags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;wcag2a&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;wcag2aa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;wcag21a&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;wcag21aa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;wcag22aa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p><code>AxeBuilder.analyze()</code> and a shared fixture are the first-party Playwright recommendation (<a href="https://playwright.dev/docs/accessibility-testing#using-a-test-fixture-for-common-axe-configuration" target="_blank" rel="noreferrer">guide</a>); axe-core defines <code>wcag22aa</code> as its WCAG 2.2 Level AA tag (<a href="https://github.com/dequelabs/axe-core/blob/develop/doc/API.md#axe-core-tags" target="_blank" rel="noreferrer">tag list</a>). Do not exclude shell, chart, form, or overlay selectors. Scan the complete page after each meaningful state is visibly settled, including open confirmations, because CDK overlays are attached outside the route component subtree.</p><p>At minimum, the meaningful-state matrix should include initial loading, success, empty, stale-after-success, and first-load error where applicable; Metrics populated/table/filtered states; Operations confirmation, pending, success, problem, cooldown, and backup-list states; and Security current/other sessions, revocation confirmation, audit filter, and next-page states.</p><p>Axe does not prove WCAG conformance; axe-core reports that automated rules find only a portion of accessibility defects and can return incomplete results that need manual review (<a href="https://github.com/dequelabs/axe-core#the-accessibility-rules" target="_blank" rel="noreferrer">scope statement</a>). Retain explicit keyboard/focus assertions and record the accepted manual 200% zoom and screen-reader-equivalent table review. Playwright can automate <code>forcedColors: &#39;active&#39;</code> and <code>reducedMotion: &#39;reduce&#39;</code> through <code>page.emulateMedia()</code> (<a href="https://playwright.dev/docs/api/class-page#page-emulate-media" target="_blank" rel="noreferrer">API</a>), but a smaller viewport is not evidence of real 200% browser zoom.</p><h2 id="implementation-checklist" tabindex="-1">Implementation checklist <a class="header-anchor" href="#implementation-checklist" aria-label="Permalink to &quot;Implementation checklist&quot;">​</a></h2><ol><li>Share the patched five-field ng-forge adapter across Metrics, Operations, and Security, with one provider per lazy route.</li><li>Keep Overview and Configuration free of ng-forge/Chart.js; keep Chart.js confined to Metrics.</li><li>Add only exact <code>@axe-core/playwright@4.13.0</code> as a new development dependency.</li><li>Register only the nine Chart.js symbols above; retain the existing hard initial, per-script, and total raw/gzip/Brotli budgets.</li><li>Exercise real production CSP with the native modal open and every chart rendered before claiming compatibility.</li><li>Keep screenshots/video/GIF proof in Playwright output or temporary storage and upload it directly to the pull request; do not add it to the repository.</li></ol>`,38)])])}const u=a(s,[["render",o]]);export{g as __pageData,u as default};
